namespace Harborline.Kernel.SchemaValidation.Records;

/// <summary>The authored identity and fields of one Record Type definition.</summary>
public sealed record RecordTypeDefinition(string RecordTypeId, IReadOnlyList<FieldDefinition> Fields);

/// <summary>An authored Record Type field whose stable identity is its containing type and key.</summary>
/// <param name="FieldKey">The field's stable key within its record type.</param>
/// <param name="DisplayName">The author-facing label; not an identity.</param>
/// <param name="Binding">The field-runtime kind and constraint floor, including the one value domain.</param>
public sealed record FieldDefinition(string FieldKey, string DisplayName, FieldBindingDefinition? Binding = null);

/// <summary>Validates the Records identity contract before a definition can mutate the schema registry.</summary>
public sealed class RecordsIntentValidator
{
    /// <summary>Returns every identity refusal for a candidate and its optional preceding version.</summary>
    public IReadOnlyList<FieldRefusal> Validate(
        RecordTypeDefinition candidate,
        RecordTypeDefinition? previousVersion)
    {
        ArgumentNullException.ThrowIfNull(candidate);

        var refusals = new List<FieldRefusal>();
        if (string.IsNullOrWhiteSpace(candidate.RecordTypeId))
        {
            refusals.Add(new(
                "records.identity.record_type_id_required",
                "/record_type_id",
                "record_type_id is required."));
        }

        if (previousVersion is not null && !string.Equals(
                candidate.RecordTypeId,
                previousVersion.RecordTypeId,
                StringComparison.Ordinal))
        {
            refusals.Add(new(
                "records.identity.record_type_id_immutable",
                "/record_type_id",
                "record_type_id cannot change within one definition's version history."));
        }

        var fieldKeys = new HashSet<string>(StringComparer.Ordinal);
        foreach (var (field, index) in (candidate.Fields ?? []).Select((field, index) => (field, index)))
        {
            if (string.IsNullOrWhiteSpace(field.FieldKey))
            {
                refusals.Add(new(
                    "records.identity.field_key_required",
                    $"/fields/{index}/field_key",
                    "field_key is required."));
                continue;
            }

            if (!fieldKeys.Add(field.FieldKey))
            {
                refusals.Add(new(
                    "records.identity.duplicate_field_key",
                    $"/fields/{index}/field_key",
                    "field_key must be unique within its record type."));
            }
        }

        return refusals;
    }
}

/// <summary>The result of compiling one Record Type grammar to a registered schema.</summary>
public sealed record RecordTypeSchemaCompilation(Schema? Schema, IReadOnlyList<FieldRefusal> Refusals);

/// <summary>Compiles admitted Record Type grammar to a draft 2020-12 JSON Schema document.</summary>
public sealed class RecordTypeSchemaCompiler
{
    private readonly RecordsIntentValidator _intentValidator;
    private readonly IFieldKindRuntime? _fieldKindRuntime;
    private readonly IValueDomainAdmission? _valueDomainAdmission;

    /// <summary>Creates a compiler using the supplied identity validator and field-runtime admission.</summary>
    public RecordTypeSchemaCompiler(
        RecordsIntentValidator? intentValidator = null,
        IFieldKindRuntime? fieldKindRuntime = null,
        IValueDomainAdmission? valueDomainAdmission = null)
    {
        _intentValidator = intentValidator ?? new RecordsIntentValidator();
        _fieldKindRuntime = fieldKindRuntime;
        _valueDomainAdmission = valueDomainAdmission;
    }

    /// <summary>
    /// Validates a candidate before registering its derived schema. Refused candidates never mutate the registry.
    /// </summary>
    public async ValueTask<RecordTypeSchemaCompilation> CompileAndRegisterAsync(
        RecordTypeDefinition candidate,
        RecordTypeDefinition? previousVersion,
        ISchemaRegistry schemaRegistry,
        CancellationToken cancellationToken = default)
    {
        ArgumentNullException.ThrowIfNull(candidate);
        ArgumentNullException.ThrowIfNull(schemaRegistry);

        var refusals = new List<FieldRefusal>(_intentValidator.Validate(candidate, previousVersion));
        var properties = new Dictionary<string, object>(StringComparer.Ordinal);
        foreach (var (field, index) in (candidate.Fields ?? []).Select((field, index) => (field, index)))
        {
            if (BindField(field.Binding, $"/fields/{index}/binding", refusals) is { } fieldSchema
                && refusals.Count == 0)
            {
                properties.Add(field.FieldKey, fieldSchema);
            }
        }

        if (refusals.Count != 0)
        {
            return new(null, refusals.AsReadOnly());
        }

        var document = new Dictionary<string, object>
        {
            ["$schema"] = "https://json-schema.org/draft/2020-12/schema",
            ["type"] = "object",
            ["properties"] = properties,
            ["additionalProperties"] = false,
        };
        var schema = await schemaRegistry.RegisterAsync(
            JsonSerializer.Serialize(document),
            cancellationToken: cancellationToken);
        return new(schema, []);
    }

    // The kind's schema and the value domain's source count are the field runtime's rules;
    // Records only routes each binding to them and keeps the authored pointer.
    private object? BindField(FieldBindingDefinition? binding, string pointer, List<FieldRefusal> refusals)
    {
        if (binding is null)
        {
            return new Dictionary<string, string> { ["type"] = "string" };
        }

        if (_fieldKindRuntime is null || _valueDomainAdmission is null)
        {
            refusals.Add(new(
                "records.field.runtime_required",
                pointer,
                "A bound field requires the field runtime to admit its kind and value domain."));
            return null;
        }

        if (binding.Constraints?.ValueDomain is { } domain)
        {
            refusals.AddRange(_valueDomainAdmission.Validate(domain, pointer + "/constraints/value_domain"));
        }

        try
        {
            return _fieldKindRuntime.Bind(binding.Kind, pointer + "/kind").JsonSchema;
        }
        catch (FieldAdmissionException exception)
        {
            refusals.AddRange(exception.Refusals);
            return null;
        }
    }
}

namespace Harborline.Kernel.SchemaValidation;

/// <summary>A content-derived identifier for a registered JSON Schema document.</summary>
public readonly record struct SchemaId
{
    /// <summary>Creates a non-empty schema identifier.</summary>
    public SchemaId(string value)
    {
        if (string.IsNullOrWhiteSpace(value))
        {
            throw new ArgumentException("Schema id must not be empty.", nameof(value));
        }

        Value = value;
    }

    /// <summary>Gets the wire value.</summary>
    public string Value { get; }

    /// <inheritdoc />
    public override string ToString() => Value;
}

/// <summary>A registered, content-addressed JSON Schema document.</summary>
public sealed record Schema(
    SchemaId Id,
    string JsonSchemaText,
    IReadOnlyList<SchemaId> ParentSchemas,
    IReadOnlyList<string> Tags,
    string ContentAddress);

/// <summary>The result of validating one payload against one registered schema.</summary>
public sealed record SchemaValidationResult(
    bool IsValid,
    IReadOnlyList<SchemaValidationError> Errors);

/// <summary>A stable, localizable validation failure addressed by RFC 6901 JSON Pointer.</summary>
public sealed record SchemaValidationError(
    string JsonPointer,
    string Message,
    string? Code = null,
    IReadOnlyDictionary<string, string>? Params = null);

/// <summary>Registers and validates the JSON Schemas used by Dynamic Forms.</summary>
public interface ISchemaRegistry
{
    /// <summary>Gets a registered schema or null when it is unknown.</summary>
    ValueTask<Schema?> GetAsync(SchemaId id, CancellationToken cancellationToken = default);

    /// <summary>Registers a draft 2020-12 schema idempotently by canonical content.</summary>
    ValueTask<Schema> RegisterAsync(
        string jsonSchemaText,
        IReadOnlyList<SchemaId>? parents = null,
        IReadOnlyList<string>? tags = null,
        CancellationToken cancellationToken = default);

    /// <summary>Validates UTF-8 JSON against a registered schema.</summary>
    ValueTask<SchemaValidationResult> ValidateAsync(
        SchemaId id,
        ReadOnlyMemory<byte> documentBytes,
        CancellationToken cancellationToken = default);

    /// <summary>Lists registered schemas, optionally filtered by an exact tag.</summary>
    IAsyncEnumerable<Schema> ListAsync(
        string? tagFilter = null,
        CancellationToken cancellationToken = default);
}

/// <summary>Thrown when a schema cannot be parsed safely as draft 2020-12 JSON Schema.</summary>
public sealed class InvalidSchemaException : Exception
{
    /// <summary>Creates an invalid-schema failure.</summary>
    public InvalidSchemaException(string message) : base(message) { }

    /// <summary>Creates an invalid-schema failure with its parser cause.</summary>
    public InvalidSchemaException(string message, Exception innerException)
        : base(message, innerException) { }
}

/// <summary>Thrown when validation names a schema that is not registered.</summary>
public sealed class SchemaNotFoundException : Exception
{
    /// <summary>Creates an unknown-schema failure.</summary>
    public SchemaNotFoundException(string message) : base(message) { }
}

/// <summary>Resource bounds applied before or during schema evaluation.</summary>
public sealed class SchemaRegistryOptions
{
    /// <summary>The default maximum canonical schema size.</summary>
    public const int DefaultMaxSchemaBytes = 256 * 1024;
    /// <summary>The default maximum schema JSON nesting depth.</summary>
    public const int DefaultMaxNestingDepth = 64;

    /// <summary>Gets the maximum canonical schema size.</summary>
    public int MaxSchemaBytes { get; init; } = DefaultMaxSchemaBytes;

    /// <summary>Gets the maximum schema JSON nesting depth.</summary>
    public int MaxNestingDepth { get; init; } = DefaultMaxNestingDepth;

    /// <summary>Gets the maximum duration of one schema pattern match.</summary>
    public TimeSpan PatternMatchTimeout { get; init; } = TimeSpan.FromMilliseconds(200);

    /// <summary>Gets the default resource bounds.</summary>
    public static SchemaRegistryOptions Default { get; } = new();

    internal void Validate()
    {
        if (MaxSchemaBytes <= 0) throw new ArgumentOutOfRangeException(nameof(MaxSchemaBytes));
        if (MaxNestingDepth <= 0) throw new ArgumentOutOfRangeException(nameof(MaxNestingDepth));
        if (PatternMatchTimeout <= TimeSpan.Zero || PatternMatchTimeout == Timeout.InfiniteTimeSpan)
        {
            throw new ArgumentOutOfRangeException(nameof(PatternMatchTimeout));
        }
    }
}

using System.Text.Json;
using System.Text.RegularExpressions;
using Json.Schema;
using Harborline.Contracts.Fields;

namespace Harborline.Kernel.SchemaValidation;

internal static class TimedSchemaDialect
{
    private static readonly Uri Draft202012Id = new("https://json-schema.org/draft/2020-12/schema");

    internal static BuildOptions Build(TimeSpan timeout, IFieldKindRuntime? fieldKindRuntime)
    {
        var standardKeywords = new[]
            {
                Vocabulary.Draft202012_Core,
                Vocabulary.Draft202012_Applicator,
                Vocabulary.Draft202012_Validation,
                Vocabulary.Draft202012_MetaData,
                Vocabulary.Draft202012_FormatAnnotation,
                Vocabulary.Draft202012_Content,
                Vocabulary.Draft202012_Unevaluated,
            }
            .SelectMany(vocabulary => vocabulary.Keywords)
            .GroupBy(keyword => keyword.Name, StringComparer.Ordinal)
            .Select(group => group.First())
            .Where(handler => handler.Name != "pattern")
            .Append((IKeywordHandler)new TimedPatternKeyword(timeout))
            .Append(new FieldKindBindingKeyword(fieldKindRuntime))
            .ToList();

        var dialect = new Dialect(standardKeywords) { Id = Draft202012Id };
        var registry = new DialectRegistry();
        registry.Register(dialect);
        return new BuildOptions { Dialect = dialect, DialectRegistry = registry };
    }
}

internal sealed class TimedPatternKeyword(TimeSpan timeout) : IKeywordHandler
{
    public string Name => "pattern";

    public object? ValidateKeywordValue(JsonElement value)
        => value.ValueKind == JsonValueKind.String
            ? new Regex(value.GetString()!, RegexOptions.ECMAScript, timeout)
            : throw new ArgumentException("The `pattern` keyword value must be a string.");

    public KeywordEvaluation Evaluate(KeywordData data, EvaluationContext context)
    {
        if (context.Instance.ValueKind != JsonValueKind.String) return KeywordEvaluation.Ignore;
        var isMatch = ((Regex)data.Value!).IsMatch(context.Instance.GetString()!);
        return new KeywordEvaluation
        {
            Keyword = Name,
            IsValid = isMatch,
            ContributesToValidation = true,
            Error = isMatch ? null : "The string value did not match the required pattern.",
        };
    }

    public void BuildSubschemas(KeywordData data, BuildContext context) { }
}

